<?php
function anFinancial(mysqli $db,array $p): array {
    $bounds=anBounds($p);$previous=anBounds($p,false,true);$billWhere="created_at>=? AND created_at<? AND status IN ('pending','overdue','paid')";$paidWhere="paid_at>=? AND paid_at<? AND status='paid'";
    $billed=anNumber($db,"SELECT COALESCE(ROUND(SUM(amount)*100),0) FROM payments WHERE $billWhere",$bounds);$collected=anNumber($db,"SELECT COALESCE(ROUND(SUM(amount)*100),0) FROM payments WHERE $paidWhere",$bounds);$prevBilled=anNumber($db,"SELECT COALESCE(ROUND(SUM(amount)*100),0) FROM payments WHERE $billWhere",$previous);$prevCollected=anNumber($db,"SELECT COALESCE(ROUND(SUM(amount)*100),0) FROM payments WHERE $paidWhere",$previous);
    $live=anRow($db,"SELECT COALESCE(ROUND(SUM(IF(status IN ('pending','overdue'),amount,0))*100),0) outstanding,COALESCE(ROUND(SUM(IF(status IN ('pending','overdue') AND due_date<CURDATE(),amount,0))*100),0) overdue,COALESCE(ROUND(SUM(IF(status='pending',amount,0))*100),0) pending FROM payments");
    $cohortPaid=anNumber($db,"SELECT COALESCE(ROUND(SUM(IF(status='paid' AND paid_at IS NOT NULL AND paid_at<?,amount,0))*100),0) FROM payments WHERE $billWhere",array_merge([$p['until']],$bounds));
    $parking=anNumber($db,"SELECT COALESCE(ROUND(SUM(p.amount)*100),0) FROM payments p JOIN parking_requests pr ON pr.payment_id=p.id WHERE p.status='paid' AND p.paid_at>=? AND p.paid_at<? AND pr.request_type='visitor' AND pr.actual_check_out IS NOT NULL AND pr.fee_state NOT IN ('free','pending_rate_review','pending_account_review') AND p.amount>0",$bounds);
    $url=anLink('superadmin/unitpayments.php');$metrics=[anMetric('billed','Recorded invoice amounts',$billed,'money','Invoices created in selected period','Current stored invoice amounts; excludes rejected/rolled-forward invoices.',$url,$prevBilled),anMetric('collected','Verified payments collected',$collected,'money','Paid during selected period','One payment row, status paid and recorded paid_at; not invoice creation date.',anLink('superadmin/unitpayments.php',['tab'=>'history']),$prevCollected),anMetric('outstanding','Outstanding billing',(int)$live['outstanding'],'money','Current live balance','Pending and overdue invoices across all creation dates.',$url),anMetric('overdue','Overdue balance',(int)$live['overdue'],'money','Current live balance','Unpaid invoices whose due date is before today.',anLink('superadmin/unitpayments.php',['status'=>'overdue'])),anMetric('pending','Pending invoice amount',(int)$live['pending'],'money','Current live balance','Pending is unpaid, not collected revenue.',$url),anMetric('collection_rate','Invoice cohort collection rate',anRatio($cohortPaid,$billed),'percent','Period invoices, paid through reporting cutoff','Paid portion of the same invoice cohort; not period collections divided by unrelated new bills.'),anMetric('parking_collected','Visitor parking collected',$parking,'money','Paid during selected period','Unique linked parking invoices with confirmed positive charges.'),anMetric('historic_balance','Historical balance at period end',null,'money','Unavailable','No immutable invoice adjustment/roll-forward ledger supports a trustworthy historical balance.'),anMetric('refunds','Refunds / adjustments',null,'money','Unavailable','No authoritative refund, reversal or partial-payment ledger exists in this installation.')];
    $bills=anTrend($db,'payments','created_at',$billWhere,$bounds,$p,'COALESCE(ROUND(SUM(amount)*100),0)');$payments=anTrend($db,'payments','paid_at',$paidWhere,$bounds,$p,'COALESCE(ROUND(SUM(amount)*100),0)');$combined=anChart('billing_collection','New invoices vs payment collections',$bills,'line','money');$combined['secondary']=$payments;$combined['primary_name']='New invoice amounts';$combined['secondary_name']='Collections by payment date';
    $itemTotals='(SELECT payment_id,SUM(amount) total FROM bill_items GROUP BY payment_id)';
    $categories=anQuery($db,"SELECT bi.category label,ROUND(SUM(bi.amount)*100) value FROM bill_items bi JOIN payments p ON p.id=bi.payment_id JOIN $itemTotals totals ON totals.payment_id=p.id AND totals.total=p.amount WHERE p.status IN ('pending','overdue') GROUP BY bi.category UNION ALL SELECT 'Unallocated / reconciliation' label,COALESCE(ROUND(SUM(p.amount)*100),0) value FROM payments p LEFT JOIN $itemTotals totals ON totals.payment_id=p.id WHERE p.status IN ('pending','overdue') AND (totals.total IS NULL OR totals.total<>p.amount)")->get_result()->fetch_all(MYSQLI_ASSOC);
    $income=anQuery($db,"SELECT bi.category label,ROUND(SUM(bi.amount)*100) value FROM bill_items bi JOIN payments p ON p.id=bi.payment_id JOIN $itemTotals totals ON totals.payment_id=p.id AND totals.total=p.amount WHERE p.status='paid' AND p.paid_at>=? AND p.paid_at<? GROUP BY bi.category UNION ALL SELECT 'Unallocated / reconciliation' label,COALESCE(ROUND(SUM(p.amount)*100),0) value FROM payments p LEFT JOIN $itemTotals totals ON totals.payment_id=p.id WHERE p.status='paid' AND p.paid_at>=? AND p.paid_at<? AND (totals.total IS NULL OR totals.total<>p.amount)",array_merge($bounds,$bounds))->get_result()->fetch_all(MYSQLI_ASSOC);
    return anSection('financial',$metrics,[$combined,anChart('collections','Collection trend',$payments,'line','money'),anChart('outstanding_categories','Outstanding balance by stored category',$categories,'bar','money',$url),anChart('income_categories','Collections by stored category',$income,'bar','money'),anChart('methods','Verified payment methods',anGroup($db,'payments',"COALESCE(NULLIF(payment_channel,''),payment_method)",$paidWhere,$bounds),'donut'),anChart('payment_status','Current status of period invoices',anGroup($db,'payments','status','created_at>=? AND created_at<?',$bounds),'donut')],['Current balances are live; past balances cannot be reconstructed safely from mutable invoices. Paid records without paid_at are excluded from period collections and flagged in Data Quality.','New invoice totals and collections use different dates and may concern different invoices. Cohort collection rate uses the same invoices and cutoff.','Category allocations use actual bill items only when their sum reconciles to the invoice. The full invoice is shown as unallocated otherwise. Refunds/partial settlements are unavailable rather than assumed zero.']);
}
